<script setup lang="ts">
import {onMounted,ref,computed} from 'vue'
import {api,uid32} from '@/api/client'
import PaperPicker from '@/components/PaperPicker.vue'
type Device={id:string;name:string;instance_id:string;expires_at:number;revoked:number}
type Job={id:string;paper_id:number;device_id:string;status:string;error:string|null}
const devices=ref<Device[]>([]),jobs=ref<Job[]>([]),code=ref(''),candidate=ref<{name:string;instance_id:string}|null>(null),deviceId=ref(''),papers=ref<number[]>([]),busy=ref(false),error=ref(''),message=ref('')
const active=computed(()=>devices.value.filter(d=>!d.revoked&&d.expires_at*1000>Date.now()))
const status:Record<string,string>={pending:'等待本地接收',leased:'传输中',completed:'完成',failed:'失败'}
async function refresh(){const [d,j]=await Promise.all([api<{devices:Device[]}>('/api/zotero/devices'),api<{jobs:Job[]}>('/api/zotero/exports')]);devices.value=d.devices;jobs.value=j.jobs;if(!active.value.some(d=>d.id===deviceId.value))deviceId.value=active.value[0]?.id??''}
async function act(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';message.value='';try{await fn()}catch(e){error.value=e instanceof Error?e.message:'操作失败'}finally{busy.value=false}}
function inspect(){void act(async()=>{candidate.value=await api('/api/zotero/pair/inspect',{body:{user_code:code.value.trim().toUpperCase()}})})}
function approve(){void act(async()=>{await api('/api/zotero/pair/approve',{body:{user_code:code.value.trim().toUpperCase()}});candidate.value=null;code.value='';message.value='已授权。请回到 Zotero 关闭配对提示，待插件领取凭据后刷新设备列表。'})}
function revoke(d:Device){if(!window.confirm('撤销“'+d.name+'”的连接？资料保留，插件将无法继续传输。'))return;void act(async()=>{await api('/api/zotero/devices/'+d.id,{method:'DELETE'});await refresh()})}
function send(){void act(async()=>{await api('/api/zotero/exports',{body:{device_id:deviceId.value,paper_ids:papers.value,request_key:uid32()}});papers.value=[];message.value='任务已排队，请在本地 Zotero 的工具菜单中点击“接收 Firework 待同步论文”。';await refresh()})}
function retry(j:Job){void act(async()=>{await api('/api/zotero/exports/'+j.id+'/retry',{body:{}});await refresh()})}
onMounted(()=>void act(refresh))
</script>
<template><main class="zotero-page"><header><router-link to="/">← 返回工作台</router-link><button :disabled="busy" @click="act(refresh)">刷新状态</button></header><h1>Zotero 集成</h1><p>在本地 Zotero 和 Firework 之间手动交换论文、分类、标签和 PDF。传输过程不调用研究模型。</p><p v-if="error" class="error" role="alert">{{error}}</p><p v-if="message" role="status">{{message}}</p>
<section><h2>1. 安装并配对</h2><a href="/downloads/firework-zotero-0.1.1.xpi" download>下载 Firework for Zotero 0.1.1</a><p>面向 Zotero 10.0.6–10.x。打开 Zotero → 工具 → 插件 → 从文件安装插件，选择下载的 XPI；然后在工具菜单中选择“Firework · 配对 / 连接 Firework”。</p><form @submit.prevent="inspect"><label>插件显示的配对码<input v-model="code" @input="candidate=null" required pattern="[a-fA-F0-9]{8}" maxlength="8" autocomplete="off" placeholder="8 位配对码"></label><button :disabled="busy">核对设备</button></form><div v-if="candidate" class="confirmation"><strong>{{candidate.name}}</strong><p>实例：{{candidate.instance_id}}</p><p>此设备可读写当前账号的同步书目和 PDF，连接 30 天有效。仅授权你刚刚发起配对的设备。</p><button class="primary" :disabled="busy" @click="approve">确认授权此设备</button></div></section>
<section><h2>2. 从 Zotero 导入</h2><p>在 Zotero 选中文献或分类，使用工具菜单中的“发送所选论文到 Firework”或“发送当前分类到 Firework”。分类层级和标签随书目保存；缺失的本地 PDF 可补齐后重试。原生批注和阅读位置暂不交换。</p><ul><li v-for="d in devices" :key="d.id"><span>{{d.name}} · {{d.revoked?'已撤销':d.expires_at*1000<=Date.now()?'已过期':'已连接'}} · 到期 {{new Date(d.expires_at*1000).toLocaleDateString()}}</span><button v-if="!d.revoked" :disabled="busy" @click="revoke(d)">撤销连接</button></li></ul><p v-if="!devices.length">暂无已配对设备。插件领取凭据后点击刷新。</p></section>
<section><h2>3. 发送到 Zotero</h2><p>仅发送已加入当前论文库的材料。保留现有书目，按文件内容去重；PDF 的正文、补充材料及历史版本作为附件保留。</p><label>目标设备<select v-model="deviceId"><option v-for="d in active" :key="d.id" :value="d.id">{{d.name}} · {{d.id.slice(0,6)}}</option></select></label><PaperPicker v-model="papers" @open-import="$router.push('/')"/><button class="primary" :disabled="busy||!deviceId||!papers.length||papers.length>30" @click="send">排队发送 {{papers.length}} 篇（每次最多 30 篇）</button><p>随后在 Zotero 选择目标分类，点击“接收 Firework 待同步论文”。本地客户端关闭时，任务保留等待接收。</p></section>
<section><h2>传输记录</h2><div class="table-wrap"><table><thead><tr><th>论文编号</th><th>设备</th><th>状态</th><th>说明</th><th>操作</th></tr></thead><tbody><tr v-for="j in jobs" :key="j.id"><td>{{j.paper_id}}</td><td>{{devices.find(d=>d.id===j.device_id)?.name??j.device_id.slice(0,6)}}</td><td>{{status[j.status]??j.status}}</td><td>{{j.error||'—'}}</td><td><button v-if="j.status==='failed'" :disabled="busy" @click="retry(j)">重试</button></td></tr></tbody></table></div><p v-if="!jobs.length">尚无发送任务。</p></section></main></template>
<style scoped>.zotero-page{max-width:1050px;margin:auto;padding:28px;color:var(--text)}header,form,li{display:flex;justify-content:space-between;align-items:center;gap:16px}h1{font-size:28px}h2{font-size:18px}p{line-height:1.8;font-size:14px}section{padding:22px;margin:24px 0;border:1px solid var(--border);border-radius:10px;background:var(--bg)}label{display:grid;gap:8px;margin:14px 0}form{justify-content:start;flex-wrap:wrap}input,select{padding:10px}a{color:var(--accent)}.confirmation{padding:16px;background:var(--accent-soft);border-radius:8px}.confirmation p{overflow-wrap:anywhere}.error{color:var(--danger)}ul{padding:0;list-style:none}li{padding:12px 0;border-bottom:1px solid var(--border)}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse;font-size:13px}td,th{text-align:left;padding:12px;border-bottom:1px solid var(--border)}td{max-width:350px;overflow-wrap:anywhere}.paper-picker{margin:16px 0}@media(max-width:600px){.zotero-page{padding:16px}section{padding:14px}li{align-items:start;flex-direction:column}}</style>
